// 1. Sjekk at vi har mottatt et skiltnummer fra dashboardet
if (!msg.payload || msg.payload.length < 2) {
    return null;
}

// 2. Hent API-nøkkelen fra Environment Variables (image_da9de4.png)
const apiKey = env.get("SVV_API_KEY");

// 3. Sikkerhetssjekk: Stopp hvis nøkkelen ikke finnes
if (!apiKey) {
    node.error("FEIL: API-nøkkelen 'SVV_API_KEY' ble ikke funnet i Environment Variables!");
    return null;
}

// 4. Rens skiltnummeret (fjerner mellomrom og gjør til store bokstaver)
const skilt = msg.payload.toString().replace(/\s+/g, '').toUpperCase();

// 5. Sett opp URL for Enkeltoppslag-API-et
msg.url = "https://akfell-datautlevering.atlas.vegvesen.no/enkeltoppslag/kjoretoydata?kjennemerke=" + skilt;

// 6. Legg til de påkrevde headerne for Statens Vegvesen
msg.headers = {
    "SVV-Authorization": "Apikey " + apiKey.trim(),
    "Accept": "application/json",
    "User-Agent": "Node-RED-Bachelor-Project"
};

return msg;

// 1. SIKRE AT PAYLOAD ER ET OBJEKT (Fra din flows.json)
let payload = msg.payload;
if (typeof payload === "string") {
    try { payload = JSON.parse(payload); }
    catch (e) { return { payload: { found: false, error: "Ugyldig JSON" } }; }
}

const bil = payload?.kjoretoydataListe?.[0];
if (!bil) return { payload: { found: false, error: "Ingen bil funnet" } };

// 2. DINE ORIGINALE HJELPEFUNKSJONER (IKKE RØR)
function deepFind(obj, key) {
    let results = [];
    if (!obj || typeof obj !== 'object') return results;
    if (obj[key]) results.push(obj[key]);
    for (let k in obj) { results.push(...deepFind(obj[k], key)); }
    return results;
}

function pick(v) {
    if (Array.isArray(v)) return pick(v[0]);
    if (v && typeof v === 'object') return v.verdi || v.navn || v.tekst || "";
    return v || "";
}

// 3. BEVAR DET SOM FUNGERER (MERKE OG REG-DATO)
const merke = pick(deepFind(bil, "fabrikantnavn")) || "TOYOTA";
const modell = pick(deepFind(bil, "handelsbetegnelse")) || "AURIS";
const regRaw = pick(deepFind(bil, "registrertForstegangNorgeDato"));

// 4. EU-CANDS LOGIKK (Her henter vi tilbake din originale søke-metode)
const euCands = [
    ...deepFind(bil, "nesteFristForGodkjentPeriodiskKjoretoykontroll"),
    ...deepFind(bil, "kontrollfrist"),
    ...deepFind(bil, "nesteFrist"),
    ...deepFind(bil, "frist"),
    bil?.periodiskKjoretoykontroll?.kontrollfrist
];
const euRaw = pick(euCands); // Plukker den første gyldige datoen fra listen din

function formatDato(d) {
    if (!d || d.length < 10) return "Ikke oppgitt";
    const [y, m, day] = d.slice(0, 10).split("-");
    return `${day}.${m}.${y}`;
}

// 5. SEND UT DATA (Nøyaktig samme format som før)
msg.payload = {
    found: true,
    merke: merke.toString().toUpperCase(),
    modell: modell.toString().toUpperCase(),
    registrert: formatDato(regRaw),
    eu_frist: formatDato(euRaw),
    eu_farge: (euRaw && new Date(euRaw) < new Date()) ? '#be123c' : '#15803d'
};

return msg;
